experiments = registry['data']['experiments']

def search_nested(obj, patterns, path=""):
    """Search nested dict/list for patterns, return matches with paths"""
    results = []
    if isinstance(obj, str):
        for p in patterns:
            if re.search(p, obj, re.IGNORECASE):
                results.append((path, obj[:200], p))
    elif isinstance(obj, dict):
        for k, v in obj.items():
            results.extend(search_nested(v, patterns, f"{path}.{k}"))
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            results.extend(search_nested(v, patterns, f"{path}[{i}]"))
    return results

# Patterns to detect ρ=0.6 + τ=0.8 combination
